const searchPuzzleTypes={academy:['Chronology','1896','A closure certificate and the missing class register both cite which year?'],grimm:['Cipher','THE BRIDGE','Decode WKH EULGJH using a shift of three backward.'],olympus:['Mythology','ARIADNE','Who gave Theseus the thread in the classical labyrinth story?'],asylum:['Deduction','PRESERVE','What should you do to original evidence before altering any working copy? (one word)'],studio:['Sequence','04050607','Put reel numbers 07, 04, 06, 05 into ascending order, without separators.'],library:['Book cipher','EIGHT','Eight witnesses, seven erased: spell the number of total witnesses.'],signal:['Code logic','TRUE','In JavaScript, what Boolean value should archivePreserved hold?']};
function searchState(){if(!state.search||typeof state.search!=='object')state.search={found:{},puzzles:{},hints:{}};return state.search}
function sceneSolved(s){return (searchState().found[s.id]||[]).length===s.items.length}
function searchHub(){const ss=searchState(),count=searchScenes.filter(sceneSolved).length,items=Object.values(ss.found).reduce((a,b)=>a+b.length,0);shell(`<section class="hero"><div><div class="eyebrow">GEROUGE INVESTIGATION · INTERACTIVE SCENE SEARCHES</div><h1>The Hidden Evidence Collection</h1><p>42 unique search rooms • 252 discoverable objects • seven additional reasoning challenges. Find the objects inside each room, build your evidence chain, and complete the case puzzle.</p><p class="meta">${count}/42 scenes cleared · ${items}/252 objects collected · ${Object.keys(ss.puzzles).length}/7 reasoning puzzles solved</p></div></section><div class="grid">${setsForSearch().map(c=>`<article class="case"><div class="caseBody"><h2>${esc(c.name)}</h2><p>${c.completed}/6 rooms cleared · ${c.puzzle?'✓':'◌'} reasoning puzzle</p><div class="bar"><span style="width:${c.completed/6*100}%"></span></div><button class="btn" data-searchcase="${c.id}">Investigate six rooms →</button></div></article>`).join('')}</div>`);bindNav();document.querySelectorAll('[data-searchcase]').forEach(b=>b.onclick=()=>searchCase(b.dataset.searchcase))}
function setsForSearch(){return cases.map(c=>({id:c.id,name:c.name,completed:searchScenes.filter(s=>s.case===c.id&&sceneSolved(s)).length,puzzle:!!searchState().puzzles[c.id]}))}
function searchCase(id){const c=cases.find(v=>v.id===id)||cases[0],arr=searchScenes.filter(s=>s.case===c.id),type=searchPuzzleTypes[id],solved=!!searchState().puzzles[id];shell(`<div class="heading"><h1>${esc(c.name)} · Search Files</h1><button class="smallbtn" id="searchback">← All mysteries</button></div><p>Inspect every room for six pieces of evidence. Object positions stay stable, and your discoveries save automatically. Room clues unlock the reasoning challenge.</p><div class="grid">${arr.map((s,i)=>`<article class="case"><div class="caseBody"><div class="eyebrow">ROOM ${i+1} · ${sceneSolved(s)?'CLEARED':'ACTIVE'}</div><h3>${esc(s.title)}</h3><p>${esc(s.story)}</p><p class="small">${(searchState().found[s.id]||[]).length}/6 recovered</p><button class="btn" data-openscene="${s.id}">Enter scene →</button></div></article>`).join('')}</div><div class="panel" style="margin-top:22px"><h2>${esc(type[0])} · Final clue</h2><p>${esc(type[2])}</p>${solved?'<p class="clue">✓ Puzzle solved and recorded in your evidence journal.</p>':`<label>Your answer <input id="logicAnswer" autocomplete="off" aria-label="Puzzle answer"></label><button class="btn" id="logicSubmit">Check deduction</button><p id="logicResult" class="small"></p>`}</div>`);bindNav();$('searchback').onclick=searchHub;document.querySelectorAll('[data-openscene]').forEach(b=>b.onclick=()=>searchRoom(b.dataset.openscene));if(!solved)$('logicSubmit').onclick=()=>{const a=$('logicAnswer').value.replace(/[^a-zA-Z0-9]/g,'').toUpperCase();if(a===type[1]){searchState().puzzles[id]=true;log(`Investigation puzzle · ${c.name} · ${type[0]} solved`);save();searchCase(id)}else $('logicResult').textContent='Not quite. Recheck the prompt, and try another deduction.'}}
function searchRoom(id){const s=searchScenes.find(x=>x.id===id);if(!s)return searchHub();const ss=searchState(),found=ss.found[id]||[],complete=found.length===6;const symbols=['✉','⚿','♙','✦','⌛','✎'];const coords=[[9,17],[61,12],[35,38],[77,48],[13,74],[54,76]];shell(`<div class="heading"><h1>${esc(s.title)}</h1><button class="smallbtn" id="roomBack">← Case rooms</button></div><p class="story">${esc(s.story)}. Search carefully: six objects are hidden around the room. Select each clue directly in the scene.</p><div class="layout"><section class="panel"><div class="evidence-scene scene-${s.case}" role="group" aria-label="Interactive ${esc(s.title)} search scene"><div class="room-window"></div><div class="room-arch"></div><div class="room-table"></div><div class="room-drawer"></div><div class="room-shadow"></div>${s.items.map((item,i)=>`<button class="search-object ${found.includes(i)?'is-found':''}" style="left:${coords[i][0]}%;top:${coords[i][1]}%" data-object="${i}" aria-label="Inspect ${esc(item)}" title="Inspect object">${symbols[i]}<span class="object-sr">${esc(item)}</span></button>`).join('')}</div><p class="small">The interactive illustration is a stylized room diagram; the object hotspots correspond to the search list. Clues are reachable by keyboard as well as mouse.</p><div class="actions"><button class="smallbtn" id="searchHint">Show a hint</button><button class="smallbtn" id="sceneNext">Next search room →</button></div><p id="searchFeedback" class="clue" aria-live="polite">${complete?'All six objects recovered. Scene report filed.':'Select a symbol to inspect an object.'}</p></section><aside class="panel side"><div class="eyebrow">EVIDENCE RECOVERY</div><h2>${found.length}/6 Objects Found</h2><div class="bar"><span style="width:${found.length/6*100}%"></span></div><h3>Search checklist</h3>${s.items.map((item,i)=>`<p class="small ${found.includes(i)?'evidence-found':''}">${found.includes(i)?'✓':'○'} ${esc(item)}</p>`).join('')}<hr class="divider"><h3>Case finding</h3><p>${complete?esc(s.finding):'Recover all six objects to file the scene report.'}</p><p class="small">Findings and cleared rooms are retained in your browser save.</p></aside></div>`);bindNav();$('roomBack').onclick=()=>searchCase(s.case);$('sceneNext').onclick=()=>{const arr=searchScenes.filter(x=>x.case===s.case),next=arr[(arr.findIndex(x=>x.id===s.id)+1)%arr.length];searchRoom(next.id)};$('searchHint').onclick=()=>{const i=s.items.findIndex((_,k)=>!found.includes(k));$('searchFeedback').textContent=i<0?'Every object is recovered.':`Look near the ${['upper left','upper right','center','right wall','lower left','lower center'][i]} part of the room for the ${s.items[i]}.`};document.querySelectorAll('[data-object]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.object),f=searchState().found[s.id]||[];if(f.includes(i))return;f.push(i);searchState().found[s.id]=f;if(f.length===6){if(!state.evidence.includes(s.finding))state.evidence.push(s.finding);log(`Search completed · ${s.title}: all six objects documented.`)}else log(`Recovered ${s.items[i]} · ${s.title}`);save();searchRoom(s.id);$('searchFeedback').textContent=f.length===6?'Case scene complete! Your report is filed in the evidence journal.':`Recovered: ${s.items[i]}. ${6-f.length} objects remain.`})}
const oldShell=shell;
shell=function(content){oldShell(content);const nav=document.querySelector('.topnav');if(nav){const b=document.createElement('button');b.className='navbtn '+(state.screen==='search'?'active':'');b.textContent='🔎 Hidden Evidence';b.onclick=()=>{state.screen='search';save();searchHub()};nav.appendChild(b)}};
const originalGo=go;go=function(screen,id){if(screen==='search'){state.screen='search';save();searchHub();scrollTo(0,0)}else originalGo(screen,id)};
const originalRender=render;render=function(){if(state.screen==='search')searchHub();else originalRender()};


