function chapelData(){if(!state.chapel||typeof state.chapel!=='object')state.chapel={room:'gate',cleared:{},choices:{},notes:[],route:[],verdict:null};return state.chapel}
function chapelProgress(){return Object.keys(chapelData().cleared).filter(x=>chapelData().cleared[x]).length}
function chapelHub(){state.screen='chapel';save();const d=chapelData();const unlocked=childrenProgress()>=7; shell(`<section class="hero"><div class="eyebrow">THE HOLLOWING · CHAPTER TWO</div><h1>Under the Gerouge Chapel</h1><p>Someone is restoring the sealed estate in secret. Follow the eight new leads, reconstruct the missing pupils' route, and determine who altered the county's historical record.</p><p class="meta">${chapelProgress()}/8 leads verified · ${unlocked?'Seven pupil dossiers complete':'Finish the seven Missing Children dossiers to access this chapter'}</p></section><div class="panel"><h2>The investigation protocol</h2><p>Do not assume a haunting when physical evidence is available. Document clues, preserve originals, and follow the identities of the missing children. Every solved location adds a specific item to your casebook.</p>${unlocked?'<p class="clue">The chapter is unlocked. Choose a location below.</p>':'<button class="btn" data-go="children">Investigate the seven pupils →</button>'}</div><div class="grid" style="margin-top:20px">${chapelStops.map((r,i)=>`<article class="case"><div class="caseBody"><div class="eyebrow">LOCATION ${i+1} · ${d.cleared[r.id]?'✓ VERIFIED':'UNCHECKED'}</div><h3>${esc(r.place)}</h3><p>${esc(r.title)}</p><button class="btn" ${unlocked?'':'disabled'} data-chapelroom="${r.id}">${d.cleared[r.id]?'Review evidence':'Enter location'} →</button></div></article>`).join('')}</div>${chapelProgress()===8?`<div class="panel" style="margin-top:20px"><h2>Final reconstruction</h2><p>All eight leads are verified. Now weigh the evidence and submit your final finding.</p><button class="btn" id="chapelVerdict">Reconstruct the truth →</button></div>`:''}`);bindNav();document.querySelectorAll('[data-chapelroom]').forEach(b=>b.onclick=()=>chapelRoom(b.dataset.chapelroom));if($('chapelVerdict'))$('chapelVerdict').onclick=chapelVerdict}
function chapelRoom(id){const r=chapelStops.find(x=>x.id===id);if(!r)return chapelHub();const d=chapelData(),solved=!!d.cleared[id], sequence=r.kind==='sequence';d.room=id;save();shell(`<div class="heading"><h1>${esc(r.place)}</h1><button class="smallbtn" id="chapelBack">← Chapel map</button></div><div class="layout"><section><div class="panel"><div class="eyebrow">Gerouge Estate · ${esc(r.title)}</div><div class="chapel-scene chapel-${r.scene}"><div class="chapel-moon"></div><div class="chapel-window"></div><div class="chapel-desk"></div><div class="chapel-light"></div><span class="chapel-mark">✦</span></div><p class="story">${esc(r.question)}</p>${solved?`<p class="clue">✓ Investigated · ${esc(r.clue)}</p><p><b>Evidence recovered:</b> ${esc(r.item)}</p>`:r.kind==='match'?`<div class="choices">${r.choices.map((x,i)=>`<button data-chapelchoice="${i}">${esc(x)}</button>`).join('')}</div>`:r.kind==='code'?`<label>Your answer <input id="chapelAnswer" autocomplete="off" aria-label="Investigation answer"></label><button class="btn" id="chapelCheck">Verify evidence</button>`:`<div class="choices">${r.choices.map((x,i)=>`<button data-chapelseq="${i}">${esc(x)}</button>`).join('')}</div><p id="chapelSequence" class="small">Sequence: ${d.route.map(i=>r.choices[i]).join(' → ')||'No steps selected'}</p><button class="smallbtn" id="chapelReset">Reset sequence</button>`}<p id="chapelFeedback" class="small" aria-live="polite"></p></div></section><aside class="panel side"><h2>Field Notebook</h2><p>Verified leads: ${chapelProgress()} / 8</p><div class="bar"><span style="width:${chapelProgress()/8*100}%"></span></div><h3>Recovered chapter evidence</h3>${chapelStops.filter(x=>d.cleared[x.id]).map(x=>`<p class="small">✓ ${esc(x.item)}</p>`).join('')||'<p class="small">No leads verified yet.</p>'}<button class="smallbtn" data-go="journal">Open county evidence board</button></aside></div>`);bindNav();$('chapelBack').onclick=chapelHub;const complete=()=>{d.cleared[id]=true;d.route=[];if(!state.evidence.includes(r.clue))state.evidence.push(r.clue);if(!state.inventory.includes(r.item))state.inventory.push(r.item);log('Gerouge Chapel · '+r.place+': '+r.clue);save();chapelRoom(id)};const fail=()=>{$('chapelFeedback').textContent='The evidence does not support that conclusion. Examine the question and try again.'};if(solved)return;
if(r.kind==='match')document.querySelectorAll('[data-chapelchoice]').forEach(b=>b.onclick=()=>Number(b.dataset.chapelchoice)===r.answer?complete():fail());
if(r.kind==='code')$('chapelCheck').onclick=()=>{const a=$('chapelAnswer').value.toUpperCase().replace(/[^A-Z]/g,'');a===r.answer?complete():fail()};
if(sequence){document.querySelectorAll('[data-chapelseq]').forEach(b=>b.onclick=()=>{d.route.push(Number(b.dataset.chapelseq));const good=d.route.every((v,i)=>v===r.answer[i]);if(!good){d.route=[];fail()}else if(d.route.length===4){complete();return}save();$('chapelSequence').textContent='Sequence: '+(d.route.map(i=>r.choices[i]).join(' → ')||'No steps selected')});$('chapelReset').onclick=()=>{d.route=[];save();chapelRoom(id)}}}
function chapelVerdict(){if(chapelProgress()<8)return chapelHub();const d=chapelData();shell(`<section class="hero"><div class="eyebrow">THE HOLLOWING · CHAPTER TWO FINALE</div><h1>The Eighth Name</h1><p>Eight leads. Seven erased pupils. One child never enrolled. Now the evidence must be separated from the frightening legend.</p></section><div class="panel"><h2>Reconstruct the truth</h2><p>Which conclusion is most strongly supported by the recovered evidence?</p><div class="choices">${['Every missing child became a ghost, and no one survived','The Heritage Trust altered modern records; four pupil transfers were documented, three remain unresolved, and Eva Grey was deliberately excluded from the roll','The Countess must be the modern administrator because the tower contains footprints'].map((x,i)=>`<button data-verd="${i}">${esc(x)}</button>`).join('')}</div><p id="verdictResult" class="clue" aria-live="polite">${d.verdict===1?'✓ Case reconstruction saved. The chapel records are ready for the next investigation.':''}</p><button class="smallbtn" id="returnChapel">← Return to chapter map</button></div>`);bindNav();$('returnChapel').onclick=chapelHub;document.querySelectorAll('[data-verd]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.verd);if(i!==1){$('verdictResult').textContent='That conclusion goes beyond the evidence. Reconsider the physical records.';return}d.verdict=i;log('Chapter Two completed · The Eighth Name: modern forgery documented; missing children still require individual follow-up.');save();$('verdictResult').innerHTML='<b>✓ Chapter Two completed.</b> The living conspiracy is documented, but the supernatural mystery is still open. Your next lead is Eva Grey’s missing testimony—last traced to the old park pavilion.'})}
const shellBeforeChapel=shell;shell=function(content){shellBeforeChapel(content);const nav=document.querySelector('.topnav');if(nav){const b=document.createElement('button');b.className='navbtn '+(state.screen==='chapel'?'active':'');b.textContent='🕯 Chapel Investigation';b.onclick=chapelHub;nav.appendChild(b)}};
const goBeforeChapel=go;go=function(screen,id){if(screen==='chapel')chapelHub();else goBeforeChapel(screen,id)};
