function estateData(){if(!state.estate||typeof state.estate!=='object')state.estate={room:'foyer',found:{},deduced:{},interviews:{},notes:[],openHint:{}};return state.estate}
function estateSeen(r){return (estateData().found[r.id]||[]).length}
function estateUnlocked(r){const idx=estateRooms.indexOf(r);return idx===0||estateData().deduced[estateRooms[idx-1].id]}
function estateTotal(){return estateRooms.reduce((n,r)=>n+estateSeen(r),0)}
function estateHub(){state.screen='estate';save();const d=estateData(),done=estateRooms.filter(r=>d.deduced[r.id]).length;shell(`<section class="hero"><div class="eyebrow">CHAPTER THREE · THE CHILDREN'S LAST NIGHT</div><h1>Explore Gerouge Plantation</h1><p>Eight connected environments. Search each location, document four physical clues, test your deductions, and challenge the witnesses with evidence. Nothing is solved by random accusations.</p><p class="meta">${estateTotal()}/32 objects logged · ${done}/8 room deductions · ${Object.keys(d.interviews).length}/3 witness interviews</p></section><div class="panel"><h2>Estate investigation map</h2><p>Locations unlock as you document and interpret what you find. Start in the entrance hall and follow the evidence through the school wing, gardens, service grounds and chapel vault.</p><div class="estate-map">${estateRooms.map((r,i)=>`<button class="estate-map-node" data-estate="${r.id}" ${estateUnlocked(r)?'':'disabled'}><span class="map-number">${String(i+1).padStart(2,'0')}</span><b>${esc(r.name)}</b><small>${esc(r.zone)} · ${estateSeen(r)}/4 finds ${d.deduced[r.id]?'· ✓ Deduced':''}</small></button>`).join('')}</div></div><div class="panel" style="margin-top:18px"><h2>Interview room</h2><p>Interview three people connected to Gerouge. To challenge a statement, you must first recover the matching object from the estate.</p><div class="estate-map">${estateWitnesses.map(w=>`<button class="smallbtn" data-witness="${w.id}">${esc(w.name)} · ${esc(w.role)} ${d.interviews[w.id]?'✓':''}</button>`).join('')}</div></div>${done===8?`<div class="panel" style="margin-top:18px"><h2>Reconstruction of the last night</h2><p>The original records show different outcomes for the children. Four transfers are documented, three are unresolved, and the modern archive was altered. The tower also contains evidence we cannot yet explain.</p><button class="btn" id="estateFinal">Open the final case hearing</button></div>`:''}`);bindNav();document.querySelectorAll('[data-estate]').forEach(b=>b.onclick=()=>estateRoom(b.dataset.estate));document.querySelectorAll('[data-witness]').forEach(b=>b.onclick=()=>estateInterview(b.dataset.witness));if($('estateFinal'))$('estateFinal').onclick=estateHearing}
function estateRoom(id){const r=estateRooms.find(r=>r.id===id);if(!r||!estateUnlocked(r))return estateHub();state.screen='estate';const d=estateData();d.room=id;save();const found=d.found[id]||[],complete=found.length===4;shell(`<div class="heading"><div><div class="eyebrow">${esc(r.zone)} · Scene ${estateRooms.indexOf(r)+1}/8</div><h1>${esc(r.name)}</h1></div><button class="smallbtn" id="estateBack">← Estate map</button></div><div class="layout"><section><div class="panel"><p class="story">${esc(r.desc)}</p><div class="estate-scene estate-${r.id} enhanced-room" style="--room-art:url('scenes/${r.id}.svg')" role="group" aria-label="Interactive illustrated ${esc(r.name)} search room"><div class="estate-atmosphere"><div class="estate-window"></div><div class="estate-furnishing left"></div><div class="estate-furnishing right"></div><div class="estate-floor"></div></div>${r.objects.map((o,i)=>`<button class="estate-object ${found.includes(i)?'collected':''}" style="left:${o[1]}%;top:${o[2]}%" data-find="${i}" aria-label="Inspect object near ${o[1]} percent across, ${o[2]} percent down" title="Examine potential evidence">${found.includes(i)?'✓':''}</button>`).join('')}</div><p id="estateFeedback" class="clue" aria-live="polite">${complete?'All four clues logged. Test your deduction.':'Search the furnished room for the items on your evidence list. Use a hint if needed.'}</p><button id="estateHint" class="smallbtn">Reveal next clue location</button></div><div class="panel" style="margin-top:18px"><h2>Investigator's deduction</h2><p>${esc(r.question)}</p>${complete?`<div class="choices">${r.answers.map((a,i)=>`<button data-deduce="${i}" ${d.deduced[id]?'disabled':''}>${esc(a)}</button>`).join('')}</div><p class="clue">${d.deduced[id]?'✓ Your conclusion is logged and the next location is unlocked.':'Compare the recovered evidence before choosing.'}</p>`:'<p class="small">Document all four objects to unlock the evidence comparison.</p>'}</div></section><aside class="panel side"><h2>Scene inventory</h2><p>${found.length}/4 clues documented</p><div class="bar"><span style="width:${found.length*25}%"></span></div>${r.objects.map((o,i)=>`<div class="estate-evidence"><b>${found.includes(i)?'✓ '+esc(o[0]):'○ '+esc(o[0])}</b>${found.includes(i)?`<p>${esc(o[3])}</p>`:''}</div>`).join('')}<button class="smallbtn" data-go="journal">Open county evidence board</button></aside></div>`);bindNav();$('estateBack').onclick=estateHub;$('estateHint').onclick=()=>{const i=r.objects.findIndex((_,i)=>!found.includes(i));$('estateFeedback').textContent=i<0?'Every clue is documented.':'Look around '+r.objects[i][1]+'% across the room and '+r.objects[i][2]+'% down.'};document.querySelectorAll('[data-find]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.find);if(found.includes(i))return;found.push(i);d.found[id]=found;if(!state.inventory.includes(r.objects[i][0]))state.inventory.push(r.objects[i][0]);const note=r.name+': '+r.objects[i][0]+' — '+r.objects[i][3];d.notes.unshift(note);log('Gerouge Estate · '+note);save();estateRoom(id);$('estateFeedback').textContent=r.objects[i][0]+': '+r.objects[i][3]});document.querySelectorAll('[data-deduce]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.deduce)!==r.correct){b.textContent='Not supported by the evidence—try another clue';return}d.deduced[id]=true;log('Estate deduction complete · '+r.name);save();estateRoom(id)})}
function estateInterview(id){const w=estateWitnesses.find(w=>w.id===id);if(!w)return estateHub();const d=estateData();state.screen='estate';save();const solved=!!d.interviews[id];shell(`<div class="heading"><h1>Interview: ${esc(w.name)}</h1><button class="smallbtn" id="interviewBack">← Return to estate</button></div><div class="layout"><section><div class="panel"><div class="eyebrow">Witness testimony · ${esc(w.role)}</div><div class="witness-portrait" aria-hidden="true">♟</div><p class="story">${esc(w.intro)}</p><h2>Recorded statements</h2>${w.statements.map((s,i)=>`<div class="task"><p><b>Statement ${i+1}:</b> “${esc(s[0])}”</p><p class="small">Evidence to compare: ${esc(s[2])}</p><button class="smallbtn" data-ask="${i}">${esc(s[2])} — Present evidence</button></div>`).join('')}<p id="interviewFeedback" class="clue" aria-live="polite">${solved?'✓ This interview is filed in the investigation record.':'Use something you actually recovered, not a guess.'}</p></div></section><aside class="panel side"><h2>Interview method</h2><p>Compare a witness's claims with physical records. Contradictions do not automatically prove guilt.</p><p>Recovered estate objects: ${estateTotal()}/32</p></aside></div>`);bindNav();$('interviewBack').onclick=estateHub;document.querySelectorAll('[data-ask]').forEach(b=>b.onclick=()=>{const s=w.statements[Number(b.dataset.ask)],owned=estateRooms.some(r=>r.objects.some((o,i)=>o[0]===s[2]&&(d.found[r.id]||[]).includes(i)));if(!owned){$('interviewFeedback').textContent='You have not recovered '+s[2]+'. Find the evidence before confronting the witness.';return}d.interviews[id]=true;log('Interview · '+w.name+': '+s[1]);save();$('interviewFeedback').textContent='Witness challenged: '+s[1]+' The exchange has been added to your journal.'})}
function estateHearing(){if(estateRooms.some(r=>!estateData().deduced[r.id]))return estateHub();const d=estateData();shell(`<section class="hero"><div class="eyebrow">CHAPTER THREE FINALE</div><h1>The Hearing of the Lost Children</h1><p>You've documented the rooms. Now decide which finding can be stated responsibly.</p></section><div class="panel"><h2>What does the physical evidence prove?</h2><div class="choices">${['Every child died in the tower','Four documented transfers exist, three outcomes remain unknown, and the Heritage Trust digitized record is inconsistent with the original','The supernatural presence caused the modern document edits'].map((x,i)=>`<button data-hearing="${i}">${x}</button>`).join('')}</div><p id="hearingFeedback" class="clue" aria-live="polite"></p><button class="smallbtn" id="hearingBack">← Estate investigation</button></div>`);bindNav();$('hearingBack').onclick=estateHub;document.querySelectorAll('[data-hearing]').forEach(b=>b.onclick=()=>{if(b.dataset.hearing!=='1'){$('hearingFeedback').textContent='The available evidence does not establish that claim. Keep separate what is proved from what is feared.';return}d.hearing=true;log('Chapter Three: the evidence-based hearing is complete.');save();$('hearingFeedback').textContent='✓ Finding entered. The missing girls’ stories remain central, while the origin of the impossible tower reflection remains unresolved.'})}
