function finaleHub(){state.screen='finale';save();const f=finaleData(),isDone=finaleProgress()===16;const interviews=Object.keys(estateData().interviews).length;const hearing=!!estateData().hearing;
shell(`<section class="hero"><div class="eyebrow">FINAL CHAPTER · THE NAMES THEY BURIED</div><h1>The Last Roll Call</h1><p>Seven missing girls. Four documented transfers. Three unresolved lives. A modern conspiracy—and something beneath the tower that refuses to be forgotten. Investigate each remaining chamber and bring the record into the light.</p><p class="meta">${finaleProgress()}/16 final objects · ${f.timeline.length}/4 timeline events · ${f.cipher?'Cipher solved':'Cipher unsolved'} · ${interviews}/3 interviews · ${hearing?'Hearing complete':'Hearing pending'}</p></section><div class="panel"><h2>Search the last four locations</h2><div class="estate-map">${finaleScenes.map((r,i)=>`<button class="estate-map-node" data-final-scene="${i}"><span class="map-number">0${i+1}</span><b>${esc(r.name)}</b><small>${esc(r.tag)} · ${(f.found[i]||[]).length}/4 objects</small></button>`).join('')}</div></div><div class="panel" style="margin-top:18px"><h2>Reconstruct the last night</h2><p>Use the independent evidence to order the events. A wrong attempt can be retried.</p><button class="btn" id="finalTimeline" ${isDone?'':'disabled'}>Open chronological evidence puzzle</button> <button class="smallbtn" id="finalCipher" ${isDone?'':'disabled'}>Decode the girls’ message</button></div><div class="panel" style="margin-top:18px"><h2>Present the final findings</h2><p>To conclude the case, recover all sixteen objects, solve the timeline and cipher, complete the estate hearing, and interview three witnesses.</p><button class="btn" id="finalVerdict" ${isDone&&f.timeline.length===4&&f.cipher&&interviews===3&&hearing?'':'disabled'}>Convene the truth commission →</button><p class="small">${!hearing?'Return to the estate map to complete the earlier evidence hearing. ':''} ${interviews<3?'Interview the groundskeeper, archivist and retired caretaker.':''}</p><button class="smallbtn" id="finalEstate">← Return to plantation</button></div>`);
bindNav();document.querySelectorAll('[data-final-scene]').forEach(b=>b.onclick=()=>finaleRoom(+b.dataset.finalScene));$('finalTimeline').onclick=finaleTimeline;$('finalCipher').onclick=finaleCipher;$('finalVerdict').onclick=finaleVerdict;$('finalEstate').onclick=estateHub;}
function finaleRoom(i){const r=finaleScenes[i],f=finaleData(),found=f.found[i]||[];state.screen='finale';save();shell(`<div class="heading"><div><div class="eyebrow">${esc(r.tag)} · Final search ${i+1}/4</div><h1>${esc(r.name)}</h1></div><button class="smallbtn" id="finalBack">← Final dossier</button></div><div class="layout"><section><div class="panel"><p>Search carefully. Find and document four objects. Their positions are fixed, so the scene can be revisited without losing progress.</p><div class="estate-scene final-scene final-scene-${i} enhanced-room" style="--room-art:url('scenes/final-${i}.svg')" role="group" aria-label="Interactive illustrated ${esc(r.name)}"><div class="estate-atmosphere"><div class="estate-window"></div><div class="estate-furnishing left"></div><div class="estate-furnishing right"></div><div class="estate-floor"></div></div>${r.items.map((o,j)=>`<button class="estate-object ${found.includes(j)?'collected':''}" style="left:${o[1]}%;top:${o[2]}%" data-final-find="${j}" aria-label="Inspect evidence near ${o[1]} percent across and ${o[2]} percent down" title="Examine potential evidence">${found.includes(j)?'✓':''}</button>`).join('')}</div><p id="finalFeedback" class="clue" aria-live="polite">${found.length===4?'Search complete.':'Search the scene for four objects from the evidence checklist.'}</p><button class="smallbtn" id="finalHint">Reveal next clue location</button></div></section><aside class="panel side"><h2>Recovered evidence (${found.length}/4)</h2>${r.items.map((o,j)=>`<div class="estate-evidence"><b>${found.includes(j)?'✓ '+esc(o[0]):'○ '+esc(o[0])}</b>${found.includes(j)?`<p>${esc(o[3])}</p>`:''}</div>`).join('')}</aside></div>`);bindNav();$('finalBack').onclick=finaleHub;$('finalHint').onclick=()=>{let j=r.items.findIndex((o,j)=>!found.includes(j));$('finalFeedback').textContent=j<0?'All objects recovered.':'Look '+r.items[j][1]+'% across, '+r.items[j][2]+'% down.'};document.querySelectorAll('[data-final-find]').forEach(b=>b.onclick=()=>{let j=+b.dataset.finalFind;if(found.includes(j))return;found.push(j);f.found[i]=found;const o=r.items[j];log('Final dossier · '+o[0]+': '+o[3]);if(!state.inventory.includes(o[0]))state.inventory.push(o[0]);save();finaleRoom(i);$('finalFeedback').textContent=o[0]+': '+o[3]})}
const chronology=[['1889','The estate school begins taking pupils under false promises of patronage.'],['1896 · dusk','The roll call omits seven girls; an evacuation plan is improvised.'],['1896 · midnight','An eighth toll warns the escape party that the tower doors are being opened.'],['Present day','A county trust employee alters the digitized register and stages a haunting.']];
function finaleTimeline(){let f=finaleData();shell(`<div class="heading"><h1>Timeline Reconstruction</h1><button id="timelineBack" class="smallbtn">← Final dossier</button></div><div class="panel"><p>Select events in historical order, from the earliest to the latest. Each correct selection is preserved.</p><div class="kv"><b>${f.timeline.length}/4 events placed</b><button class="smallbtn" id="timelineReset">Start timeline over</button></div><div class="choices">${[2,0,3,1].map(i=>`<button data-time="${i}" ${f.timeline.includes(i)?'disabled':''}>${esc(chronology[i][0])} · ${esc(chronology[i][1])}</button>`).join('')}</div><p id="timelineFeedback" class="clue">${f.timeline.length===4?'✓ Timeline reconstructed.':'Compare dates and testimony.'}</p></div>`);bindNav();$('timelineBack').onclick=finaleHub;$('timelineReset').onclick=()=>{f.timeline=[];save();finaleTimeline()};document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{let i=+b.dataset.time;if(i!==f.timeline.length){$('timelineFeedback').textContent='That event occurred later. Review the dated records.';return}f.timeline.push(i);save();finaleTimeline()})}
function finaleCipher(){let f=finaleData();shell(`<div class="heading"><h1>The Girls’ Last Message</h1><button class="smallbtn" id="cipherBack">← Final dossier</button></div><div class="panel"><p>A line was carved into the underside of the nursery window: <b>OHW WKHP EH QDPHG</b>. The inscription uses a Caesar cipher, moving each letter three places forward. Decode it to learn what the girls were asking.</p><label for="cipherAnswer">Decoded message</label><input id="cipherAnswer" autocomplete="off" placeholder="Type the hidden message" style="width:100%;padding:12px;margin:12px 0;background:#171722;color:white;border:1px solid #777;border-radius:8px"><div class="actions"><button class="btn" id="cipherSubmit">Verify inscription</button><button class="smallbtn" id="cipherClue">Show method</button></div><p class="clue" id="cipherFeedback">${f.cipher?'✓ Inscription decoded and saved.':'A becomes D when encoded. Reverse that shift to decode.'}</p></div>`);bindNav();$('cipherBack').onclick=finaleHub;$('cipherClue').onclick=()=>{$('cipherFeedback').textContent='For each letter, move three letters backward in the alphabet. OHW becomes LET.'};$('cipherSubmit').onclick=()=>{const answer=$('cipherAnswer').value.toUpperCase().replace(/[^A-Z]/g,'');if(answer!=='LETTHEMBENAMED'){$('cipherFeedback').textContent='Not quite. Work backward three letters, one character at a time.';return}f.cipher=true;log('The message reads: LET THEM BE NAMED.');save();$('cipherFeedback').textContent='✓ LET THEM BE NAMED. The final plea is now recorded.'}}
function finaleVerdict(){let f=finaleData();if(finaleProgress()!==16||f.timeline.length!==4||!f.cipher||!estateData().hearing||Object.keys(estateData().interviews).length!==3)return finaleHub();shell(`<section class="hero"><div class="eyebrow">THE LAST ROLL CALL · FINALE</div><h1>Who stole the children’s stories?</h1><p>The sealed testimonies explain why Gerouge became a legend: the original abuse was committed by people with power. Later storytellers made the Countess the only villain, while the records of living girls vanished into county archives.</p></section><div class="panel"><h2>Issue your finding</h2><p>Choose how to release the archive. Both paths protect the surviving children's identities until their descendants can be consulted.</p><div class="choices"><button data-verdict="public">Publish the verified history and preserve the unidentified girls’ privacy</button><button data-verdict="families">Contact descendants first, then publish the independently verified findings</button><button data-verdict="legend">Declare the supernatural legend proven and dismiss the archival evidence</button></div><p id="verdictFeedback" class="clue"></p></div>`);bindNav();document.querySelectorAll('[data-verdict]').forEach(b=>b.onclick=()=>{let v=b.dataset.verdict;if(v==='legend'){$('verdictFeedback').textContent='The unexplained evidence cannot establish that claim. Separate the legend from documented crimes.';return}f.verdict=v;f.epilogue='complete';state.chapter=true;log('Final case closed: '+(v==='public'?'the verified findings were published.':'descendants were consulted before publication.'));save();finaleEnding()})}
function finaleEnding(){const f=finaleData();shell(`<section class="hero"><div class="eyebrow">THE HOLLOWING · COMPLETED CASE</div><h1>The Children Have Names</h1><p>The county could no longer hide what its archives revealed. Four girls survived long enough to be transferred away. Three pupils’ final fates remain genuinely unknown, and the missing eighth name belonged to Eva Grey—the caretaker’s daughter who helped others escape.</p><p>The account does not pretend to prove how every child died. It restores their identities, exposes the 1896 cover-up, and documents the modern alteration of the records.</p></section><div class="panel"><h2>Your ending: ${f.verdict==='families'?'The Families First':'The Public Record'}</h2><p>${f.verdict==='families'?'You placed the families at the center of how the truth was released. Some asked for silence about intimate details; others shared letters that made the children’s lives vivid again.':'You published the verified findings without exposing private details that the evidence could not justify. The public demanded a fuller investigation of the county trust.'}</p><p>At dusk, you stand by the school gate. Seven ribbons move in the wind. The tower bell sounds once. This time, you know a living person might be pulling its rope. Then, from the locked classroom, you hear a child quietly say: <em>“Thank you for looking.”</em></p><p class="clue">✓ Final storyline completed. The seven other mysteries, search rooms, gardens, library and sanctuary remain available to explore.</p><div class="actions"><button class="btn" id="endingExplore">Keep exploring the county</button><button class="smallbtn" id="endingReview">Review final dossier</button></div></div>`);bindNav();$('endingExplore').onclick=()=>go('map');$('endingReview').onclick=finaleHub;}
const previousEstateHub=estateHub;estateHub=function(){previousEstateHub();const panel=document.createElement('section');panel.className='panel';panel.style.marginTop='18px';panel.innerHTML='<h2>🔔 Final Chapter: The Last Roll Call</h2><p>Enter the last four search locations and unravel the ending of the children’s story. You can begin the final searches at any time; the concluding hearing requires your estate investigations and witness testimony.</p><button class="btn" id="launchFinal">Investigate the final dossier →</button>';document.querySelector('main.wrap').appendChild(panel);$('launchFinal').onclick=finaleHub};
